using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using ElementalHearts;using Verse;
class AdamantRegression {
 static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
 static int Main(string[] args){AppDomain.CurrentDomain.AssemblyResolve+=(s,e)=>{string name=new AssemblyName(e.Name).Name;string path=name=="ElementalHearts"?args[1]:name=="0Harmony"?args[2]:Path.Combine(args[0],name+".dll");return File.Exists(path)?Assembly.LoadFrom(path):null;};try{typeof(AdamantRegression).GetMethod("Run",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,null);return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
 static void Run(){
  for(int n=0;n<9;n++)foreach(bool evolved in new[]{false,true}){var old=Enumerable.Range(0,n).Select(i=>100+i*37).ToList();var result=AdamantRules.Deadlines(old,evolved);Check(result.Count==(evolved?5:4),"compatible list length");Check(result.Take(Math.Min(old.Count,result.Count)).SequenceEqual(old.Take(result.Count)),"all pre-existing deadlines retained");Check(result.Skip(old.Count).All(i=>i==0),"new slots start ready");}
  var unchanged=new List<int>{1,2,3,4,5};Check(object.ReferenceEquals(unchanged,AdamantRules.Deadlines(unchanged,true)),"steady-state queries allocate no new cooldown list");
  Check((int)EarthPower.Cleave==0&&(int)EarthPower.Advance==1&&(int)EarthPower.Bastion==2&&(int)EarthPower.Mountainfall==3&&(int)EarthPower.Bulwark==4,"saved technique numeric meanings retained");
  Check(AdamantRules.RepathAllowed(0,5,8,64)&&!AdamantRules.RepathAllowed(1,5,8,64)&&!AdamantRules.RepathAllowed(0,9,8,64)&&!AdamantRules.RepathAllowed(0,5,8,65),"one eight-cell correction and sixteen-step total budget");
  var start=new IntVec3(20,0,20);var tree=WindNavigation.Tree(start,(a,b)=>b.x!=22,64,197);Check(tree.Count<=197&&!tree.ContainsKey(new IntVec3(22,0,20)),"bounded extended navigation cannot cross a blocked column");Check(WindNavigation.Path(tree,start,new IntVec3(21,0,20),16).Count==1,"adjacent legal route");
  var root=new HediffWithComps{def=new HediffDef{defName="EH_EarthHeart"}};var comp=new HediffComp_EarthAbilities{parent=root,props=new HediffCompProperties_EarthAbilities(),readyAt=new List<int>{101,202,303,404},autoCombat=false,nonLethal=true,guardOrigin=new IntVec3(4,0,8),guardUntil=999};root.comps=new List<HediffComp>{comp};
  Check(!comp.Evolved&&comp.SkillCount==4,"normal lineage remains four skills");root.def=new HediffDef{defName=AdamantEvolution.DefName};comp.EnsureSlots();Check(comp.Evolved&&comp.SkillCount==5&&comp.readyAt.SequenceEqual(new[]{101,202,303,404,0})&&!comp.autoCombat&&comp.nonLethal,"same component upgrades without lost preferences or cooldowns");
  var state=new AdamantSave{comp=comp};string file=Path.Combine(Path.GetTempPath(),"Adamant-"+Guid.NewGuid().ToString("N")+".xml");Scribe.saver.InitSaving(file,"AdamantTest");Scribe_Deep.Look(ref state,"state");Scribe.saver.FinalizeSaving();var xml=new System.Xml.XmlDocument();xml.Load(file);Check(xml.SelectNodes("AdamantTest/state/EH_earthReadyAt/li").Count==5&&xml.SelectSingleNode("AdamantTest/state/EH_earthAuto").InnerText=="False"&&xml.SelectSingleNode("AdamantTest/state/EH_earthNonLethal").InnerText=="True","native Scribe uses compatible Earth keys for evolved state");Check(xml.SelectSingleNode("AdamantTest/state/EH_adamantGuardOrigin")!=null&&xml.SelectSingleNode("AdamantTest/state/EH_earthGuardUntil").InnerText=="999","native guard origin and expiry persist");File.Delete(file);
  var f=BindingFlags.Instance|BindingFlags.NonPublic;Check(((Array)typeof(MapComponent_Earth).GetField("effects",f).GetValue(new MapComponent_Earth(null))).Length==96,"shared effect pool remains bounded");Check(((Array)typeof(MapComponent_EarthPushVisual).GetField("pushes",f).GetValue(new MapComponent_EarthPushVisual(null))).Length==32,"cosmetic push pool remains bounded");
  Console.WriteLine("PASS: "+checks+" Adamant compatibility, deadline/slot, Scribe, bounded navigation and visual-pool checks.");
 }
}
public class AdamantSave:IExposable {public HediffComp_EarthAbilities comp;public void ExposeData(){comp.CompExposeData();}}
